mapper.select:
SELECT *
FROM (
SELECT *,
@row_number:=CASE WHEN @current_device = device_id THEN @row_number + 1 ELSE 1 END AS rn,
@current_device:=device_id
FROM data_real, (SELECT @row_number:=0, @current_device:=NULL) AS t
WHERE `time` BETWEEN #{startTime} AND #{endTime}
ORDER BY device_id, `time` ASC
) AS temp
WHERE temp.rn = 1;

SELECT *
FROM (
SELECT *,
@row_number:=CASE WHEN @current_device = device_id THEN @row_number + 1 ELSE 1 END AS rn,
@current_device:=device_id
FROM data_real, (SELECT @row_number:=0, @current_device:=NULL) AS t
WHERE `time` BETWEEN #{startTime} AND #{endTime}
ORDER BY device_id, `time` DESC
) AS temp
WHERE temp.rn = 1;

SELECT *
FROM (
SELECT *,
@row_number:=CASE WHEN @current_device = device_id THEN @row_number + 1 ELSE 1 END AS rn,
@current_device:=device_id
FROM data_real, (SELECT @row_number:=0, @current_device:=NULL) AS t
WHERE `time` <= #{time}
ORDER BY device_id, `time` DESC
) AS temp
WHERE temp.rn = 1;
